{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "It would add references to public charter schools in specified provisions of Tennessee’s education funding and financial reporting laws.",
      "rationale": "Conveys the addition of charter-school references but does not identify § 49-3-103(d)(3) or the language being amended."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "For funding under Section 49-3-105, the Department of Education would generally send student-generated funds to the local education agency (LEA) where the student is enrolled, but would keep funds generated under subsection (c)(3) and send directly to a public charter school the state share generated for that school’s students. A student’s membership would run from the first through the last day of enrollment",
      "rationale": "Conveys the department’s general allocation rule, its membership-based duration, and both funding exceptions."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "A student’s membership would run from the first through the last day of enrollment; for funding, an early graduate’s membership would extend to the expected graduation date.",
      "rationale": "Accurately conveys the membership period and the early-graduation funding exception."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "It would add references to public charter schools in specified provisions of Tennessee’s education funding and financial reporting laws.",
      "rationale": "Conveys the general addition but does not identify § 49-3-316(c) or its application to every occurrence of LEA."
    },
    {
      "proposition_id": "P5",
      "status": "partial",
      "summary_quote": "The commissioner, consulting with the comptroller, would establish a standard financial accounting and reporting system for all public charter schools. It would support comparisons across years and agencies and show the sources and uses of each school’s funds.",
      "rationale": "Covers the actors, system, scope, and purposes, but omits required revisions as necessary and appropriate forms or documentation."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The commissioner would review charter-school financial records to ensure funds are properly accounted for and safeguarded",
      "rationale": "Conveys the mandatory review and its accounting and safeguarding purposes; the general reference to funds encompasses the listed expenditure categories."
    },
    {
      "proposition_id": "P7",
      "status": "partial",
      "summary_quote": "could require charter schools receiving state education funds to follow one or more financial requirements that apply to LEAs.",
      "rationale": "Conveys the commissioner’s discretion and eligible schools, but does not limit the applicable LEA requirements to those established in § 49-3-316."
    },
    {
      "proposition_id": "P8",
      "status": "partial",
      "summary_quote": "Under a revised funding formula, a local school board would allocate charter schools local student-generated funds based on the prior year",
      "rationale": "Conveys the board’s allocation of prior-year local student-generated funds but omits the required alignment with TISA."
    },
    {
      "proposition_id": "P9",
      "status": "partial",
      "summary_quote": "a local school board would allocate charter schools local student-generated funds based on the prior year, certain state and local funds above TISA requirements",
      "rationale": "Mentions above-TISA state and local funding but omits the current-year district average per-pupil calculation applied to each prior-year charter member."
    },
    {
      "proposition_id": "P10",
      "status": "partial",
      "summary_quote": "a local school board would allocate charter schools local student-generated funds based on the prior year, certain state and local funds above TISA requirements, funds for membership added beyond the prior year",
      "rationale": "Conveys funding for membership growth but omits that the amount is the per-student state and local funds received by the LEA for current-year students beyond prior-year membership."
    },
    {
      "proposition_id": "P11",
      "status": "full",
      "summary_quote": "a local school board would allocate charter schools local student-generated funds based on the prior year, certain state and local funds above TISA requirements, funds for membership added beyond the prior year, and appropriate federal allocations.",
      "rationale": "Conveys the board’s obligation to provide appropriate federal allocations; the named federal programs are illustrative."
    },
    {
      "proposition_id": "P12",
      "status": "partial",
      "summary_quote": "The Department of Education would separately allocate directly to a charter school the state student-generated funds for its prior-year members.",
      "rationale": "Conveys the department’s direct allocation and prior-year membership basis but omits required alignment with TISA."
    },
    {
      "proposition_id": "P13",
      "status": "full",
      "summary_quote": "Federal funds received by an LEA would go to its authorized charter schools through either a shared-services agreement or subgrants reflecting each school’s equitable share based on eligible students, under department policies.",
      "rationale": "Conveys the authorized-school scope, both disbursement methods, equitable-share basis, and department oversight requirements."
    },
    {
      "proposition_id": "P14",
      "status": "partial",
      "summary_quote": "Each LEA would have to include in its budget the per-pupil local amount it plans to pass through to charter schools and the calculations supporting it.",
      "rationale": "Covers budget disclosure but omits the upcoming-school-year specification and the requirement that actual allocations be based on the calculated amounts."
    },
    {
      "proposition_id": "P15",
      "status": "full",
      "summary_quote": "The LEA would pay expected local funds in at least nine equal installments, in the same manner as state funds",
      "rationale": "Conveys the expected-local-funds basis, minimum number of equal installments, and required distribution manner."
    },
    {
      "proposition_id": "P16",
      "status": "full",
      "summary_quote": "The LEA would pay expected local funds in at least nine equal installments, in the same manner as state funds, and adjust payments at least in October, February, and June for changes in revenue, membership, or student services.",
      "rationale": "Conveys the required adjustment months and all three adjustment grounds."
    },
    {
      "proposition_id": "P17",
      "status": "full",
      "summary_quote": "Charter schools would have to spend funds according to their submitted budget or a revision by their governing body, subject to state and federal law.",
      "rationale": "Conveys the spending restriction, governing-body revision option, and state and federal law conditions."
    },
    {
      "proposition_id": "P18",
      "status": "full",
      "summary_quote": "Sections 1 and 3 would take effect upon becoming law. Sections 2 and 4 would take effect upon becoming law for rulemaking, and otherwise on July 1, 2025.",
      "rationale": "Accurately conveys all effective dates and the rulemaking exception."
    }
  ]
}
